deno --version && cat > main.ts <<'EOF'
// Reports the ten most frequent words in a text file.
// A word is a maximal run of ASCII letters and digits; every other byte separates words.

function isWordByte(b: number): boolean {
  return (b >= 0x30 && b <= 0x39) || (b >= 0x41 && b <= 0x5a) ||
    (b >= 0x61 && b <= 0x7a);
}

export function countWords(bytes: Uint8Array): Map<string, number> {
  const counts = new Map<string, number>();
  const n = bytes.length;
  let i = 0;
  while (i < n) {
    while (i < n && !isWordByte(bytes[i])) i++;
    if (i >= n) break;
    let word = "";
    while (i < n && isWordByte(bytes[i])) {
      let b = bytes[i];
      if (b >= 0x41 && b <= 0x5a) b += 0x20;
      word += String.fromCharCode(b);
      i++;
    }
    counts.set(word, (counts.get(word) ?? 0) + 1);
  }
  return counts;
}

export function topWords(
  counts: Map<string, number>,
  limit = 10,
): [string, number][] {
  // Words are ASCII-only, so UTF-16 code unit comparison equals byte comparison.
  return [...counts.entries()]
    .sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0))
    .slice(0, limit);
}

export function report(bytes: Uint8Array): string {
  return topWords(countWords(bytes)).map(([w, c]) => `${w} ${c}\n`).join("");
}

if (import.meta.main) {
  const path = Deno.args[0];
  if (path === undefined) {
    console.error("usage: main.ts <file>");
    Deno.exit(2);
  }
  const out = report(await Deno.readFile(path));
  if (out.length > 0) {
    await Deno.stdout.write(new TextEncoder().encode(out));
  }
}
EOF
cat > main_test.ts <<'EOF'
import { report } from "./main.ts";

const enc = new TextEncoder();
const r = (s: string | Uint8Array) =>
  report(typeof s === "string" ? enc.encode(s) : s);

function assertEquals(actual: unknown, expected: unknown) {
  if (actual !== expected) {
    throw new Error(
      `expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`,
    );
  }
}

Deno.test("empty input writes nothing", () => {
  assertEquals(r(""), "");
  assertEquals(r("  ,.!? \n\t— é"), "");
});

Deno.test("case-insensitive, lower-case output", () => {
  assertEquals(r("Hello hello HELLO world"), "hello 3\nworld 1\n");
});

Deno.test("ties broken by byte order", () => {
  assertEquals(r("b a 1 B A Z z"), "a 2\nb 2\nz 2\n1 1\n");
});

Deno.test("non-ASCII and punctuation separate words", () => {
  assertEquals(r("café don't x_y"), "caf 1\ndon 1\nt 1\nx 1\ny 1\n");
  assertEquals(r(new Uint8Array([0x61, 0xff, 0x61, 0x00, 0x62])), "a 2\nb 1\n");
});

Deno.test("only ten reported", () => {
  const words = Array.from({ length: 12 }, (_, i) => `w${i}`.repeat(1));
  const text = words.map((w, i) => (w + " ").repeat(i + 1)).join("");
  const out = r(text).trim().split("\n");
  assertEquals(out.length, 10);
  assertEquals(out[0], "w11 12");
  assertEquals(out[9], "w2 3");
});

Deno.test("digits are word characters", () => {
  assertEquals(r("abc123 ABC123 123"), "abc123 2\n123 1\n");
});
EOF
deno check main.ts main_test.ts && deno test && printf 'The the THE cat, cat; dog\n' > /tmp/wf.txt && deno run --allow-read main.ts /tmp/wf.txt; echo "exit=$?"; : > /tmp/empty.txt; deno run --allow-read main.ts /tmp/empty.txt | wc -c

